using FilamentDbApp.Models;
using System.Globalization;
using System.Net;
using System.Text.Json;
using System.Text.RegularExpressions;
namespace FilamentDbApp.Services.Reporting;
public sealed class PublicTestSessionReportPublishingService
{
    public static IReadOnlyList<string> PublicFieldAllowlist { get; } = new[] { "MaterialId", "MaterialName", "Manufacturer", "SummaryStatus", "ResultModules", "SpecimenResultRecords", "PublicDetailsApproved", "VerifiedMeasurements", "QualityRows", "Module", "Orientation", "Average", "StandardDeviation", "CoefficientOfVariation", "Samples", "Confidence", "Validation", "RawInputs", "InputSet", "RecordedValues", "ApprovedNotes", "Note" };
    private static readonly string[] Forbidden={"\"BatchNumber\"","\"Purchase","\"Inventory","\"StorageLocation\"","\"SupplierUrl\"",".sqlite"};
    public PublicTestSessionPublicationResult Build(PublicTestSessionReportModel m,DateTime at,string version,string release){var seg=PublicReportPublishingService.SafeMaterialIdSegment(m.MaterialId);if(string.IsNullOrWhiteSpace(seg))throw new InvalidOperationException("MaterialID required");if(!m.PublicDetailsApproved&&(m.RawInputs.Count>0||m.ApprovedNotes.Count>0))throw new InvalidOperationException("Raw inputs and notes require explicit public detail approval.");var dir=$"reports/test-sessions/{seg}";return new(){RelativeDirectory=dir,Html=PublicReportScreenThemeService.Apply(Html(m,at,version,release,dir)),Manifest=$"3DPIceland Public Test Session Report\nVersion: {version}\nGenerated: {at:O}\nMaterialID: {m.MaterialId}\nStable relative directory: {dir}\nCanonical HTML: index.html\nPDF from canonical HTML: report.pdf\nMetadata: report-metadata.json\nAssets: assets/\n",MetadataJson=JsonSerializer.Serialize(new{schema="3dpiceland.public-test-session-report.v1",version,generatedAt=at.ToString("O",CultureInfo.InvariantCulture),reportKey="test-session",stableRelativeDirectory=dir,canonicalHtml="index.html",pdf="report.pdf",publicFieldAllowlist=PublicFieldAllowlist,publicData=m},new JsonSerializerOptions{WriteIndented=true})};}
    public PublicComparisonVerificationResult Verify(PublicTestSessionReportModel m,PublicTestSessionPublicationResult r){var p=string.Join("\n",r.Html,r.Manifest,r.MetadataJson);var detailBoundary=m.PublicDetailsApproved||(m.RawInputs.Count==0&&m.ApprovedNotes.Count==0&&!r.Html.Contains("Recorded native inputs",StringComparison.Ordinal));var ok=r.RelativeDirectory==$"reports/test-sessions/{PublicReportPublishingService.SafeMaterialIdSegment(m.MaterialId)}"&&PublicFieldAllowlist.All(x=>r.MetadataJson.Contains($"\"{x}\"",StringComparison.Ordinal))&&Forbidden.All(x=>!p.Contains(x,StringComparison.OrdinalIgnoreCase))&&!Regex.IsMatch(p,@"(?<![A-Za-z0-9])[A-Za-z]:[\\/]")&&detailBoundary&&r.Html.Contains("Specimen and result quality",StringComparison.Ordinal)&&r.Html.Contains("Method and equipment context",StringComparison.Ordinal)&&r.Html.Contains("Not recorded",StringComparison.Ordinal)&&r.Html.Contains("assets/3dp-iceland-labs-logo-pdf.jpg",StringComparison.Ordinal);return new(){Passed=ok,Detail=ok?$"Allowlisted test-session report ready at {r.RelativeDirectory}":"Public test-session routing, content or approval boundary failed"};}
    public static string BuildPreviewIndex(IEnumerable<PublicTestSessionReportModel> ms,DateTime at)=>$"<!doctype html><html><head><meta charset=\"utf-8\"><title>Public Test Session Reports</title><style>body{{font-family:Segoe UI,Arial;margin:32px;background:#f1f5f9}}main{{max-width:900px;margin:auto;background:#fff;padding:28px}}article{{border-top:1px solid #ccc;padding:12px}}a{{color:#1d4ed8;font-weight:700}}</style></head><body><main><h1>Public Test Session Reports</h1><p>{at:yyyy-MM-dd HH:mm:ss}</p>{string.Join("",ms.Select(m=>$"<article><h2>{H(m.MaterialName)}</h2><p>{H(m.MaterialId)} &middot; details {(m.PublicDetailsApproved?"approved":"aggregate only")}</p><a href=\"reports/test-sessions/{H(PublicReportPublishingService.SafeMaterialIdSegment(m.MaterialId))}/index.html\">Open HTML</a> &middot; <a href=\"reports/test-sessions/{H(PublicReportPublishingService.SafeMaterialIdSegment(m.MaterialId))}/report.pdf\">Open PDF</a></article>"))}<p>Local preview only.</p></main></body></html>";
    private static string Html(PublicTestSessionReportModel m,DateTime at,string version,string release,string dir){var q=string.Join("",m.QualityRows.Select(x=>$"<tr><td>{H(x.Module)}</td><td>{H(x.Orientation)}</td><td>{H(x.Average)}</td><td>{H(x.StandardDeviation)}</td><td>{H(x.CoefficientOfVariation)}</td><td>{x.Samples}</td><td>{H(x.Confidence)}</td><td>{H(x.Validation)}</td></tr>"));var raw=m.PublicDetailsApproved?$"<h2>Recorded native inputs</h2><table><thead><tr><th>Module</th><th>Input set</th><th>Recorded values</th></tr></thead><tbody>{string.Join("",m.RawInputs.Select(x=>$"<tr><td>{H(x.Module)}</td><td>{H(x.InputSet)}</td><td>{H(x.RecordedValues)}</td></tr>"))}</tbody></table><h2>Approved test notes</h2><table><tbody>{string.Join("",m.ApprovedNotes.Select(x=>$"<tr><td>{H(x.Module)}</td><td>{H(x.Note)}</td></tr>"))}</tbody></table>":"<div class=\"note\"><strong>Detailed-input boundary:</strong> raw inputs and test notes are not published because Public test details is not approved for this MaterialID.</div>";return $"<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>{H(m.MaterialName)} Test Session Report</title><style>body{{font-family:Segoe UI,Arial;margin:0;background:#f1f5f9;color:#0f172a}}main{{max-width:1100px;margin:30px auto;background:#fff;padding:30px}}header,.cards{{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}}img{{width:180px}}.cards{{grid-template-columns:repeat(4,1fr)}}.card,.note{{border:1px solid #cbd5e1;padding:14px;border-radius:12px}}table{{width:100%;border-collapse:collapse;margin:12px 0 24px}}th,td{{padding:8px;border-bottom:1px solid #ddd;text-align:left}}@media(max-width:700px){{header,.cards{{grid-template-columns:1fr}}}}</style></head><body><main><header><div><strong>Public test session report</strong><h1>{H(m.MaterialName)}</h1><p>MaterialID {H(m.MaterialId)}</p></div><div><img src=\"assets/3dp-iceland-labs-logo-pdf.jpg\"><p>{H(version)} - {H(release)}<br>{at:yyyy-MM-dd HH:mm:ss}</p></div></header><div class=\"note\"><strong>Traceability boundary:</strong> current canonical test tables are MaterialID-linked records, not a dedicated session ledger. Session identifier, test timestamp, operator, printer/slicer profile and environmental conditions are Not recorded and are never inferred.</div><div class=\"cards\"><div class=\"card\">Status<br><strong>{H(m.SummaryStatus)}</strong></div><div class=\"card\">Result modules<br><strong>{m.ResultModules}/3</strong></div><div class=\"card\">Specimen/result records<br><strong>{m.SpecimenResultRecords}</strong></div><div class=\"card\">Public details<br><strong>{(m.PublicDetailsApproved?"Approved":"Aggregate only")}</strong></div></div><h2>Specimen and result quality</h2><table><thead><tr><th>Module</th><th>Orientation</th><th>Average</th><th>Std. dev.</th><th>CV</th><th>Specimens</th><th>Confidence</th><th>Validation</th></tr></thead><tbody>{q}</tbody></table>{raw}<h2>Method and equipment context</h2><div class=\"note\">Purpose-built tensile, pendulum impact and three-point bend apparatus are used with the governed Settings Manager constants consumed by ResultsService. Results are comparative and do not claim accredited-laboratory equipment.</div><p><a href=\"https://iskort.is/3dp/index.html#methodology\">Testing methodology</a> &middot; <a href=\"https://iskort.is/3dp/3DPIceland_Labs_Mechanical_Testing_Methodology_v1.0.pdf\">Engineering methodology whitepaper</a> &middot; <a href=\"report.pdf\">Download PDF</a></p><footer>{H(dir)}/</footer></main></body></html>";}
    private static string H(string? s)=>WebUtility.HtmlEncode(s??"");
}
